insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('125', 'Applicant', 'Application Approval Pending and Request for More Info', null, 'Offer contingent approval to an applicant and request more info.', '<p>Hi&nbsp;<span class="token" contenteditable="false">[[Applicant_FirstName]]</span>,</p> 
 <p>We''ve received your application! To move forward with approval, we need a bit more info from you and any of your co-applicants or co-signers. Please send the following to <span class="token" contenteditable="false">[[Sender_Email]]</span>:</p>
 <div><ul type="disc">
 <li>Proof of income (e.g., pay stubs from the last 2 pay periods or a signed employment offer letter)</li>
 <li>Proof of identity for all residents over the age of 18</li>
 <ul class="square">
 <li>US citizens: Driver''s license or United States passport</li>
 <li>Non-US citizens: Passport from country of citizenship and United States visa</li>
 </ul>
 <li>Preferred lease term (e.g., 12 or 18 months)</li>
 <li>Preferred move-in date</li>
 </ul></div>
 <p>Thank you! We''re looking forward to reviewing your additional info.</p>
 <p><br />Sincerely,<br /><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Applicant_FirstName', 'Sender_Email', 'Sender_Signature']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('126', 'Applicant', 'Request More Info from Applicant', null, 'Request more info from an applicant.', '<p>Hi&nbsp;<span class="token" contenteditable="false">[[Applicant_FirstName]]</span>,</p> 
 <p>We''ve received your application! Before we can review, we need a bit more info from you and any of your co-applicants or co-signers. Please send the following to <span class="token" contenteditable="false">[[Sender_Email]]</span>:</p>
 <div><ul type="disc">
 <li>Proof of income (e.g., pay stubs from the last 2 pay periods or a signed employment offer letter)</li>
 <li>Proof of identity for all residents over the age of 18</li>
 <ul class="square">
 <li>US citizens: Driver''s license or United States passport</li>
 <li>Non-US citizens: Passport from country of citizenship and United States visa</li>
 </ul>
 <li>Preferred lease term (e.g., 12 or 18 months)</li>
 <li>Preferred move-in date</li>
 </ul></div>
 <p>Thank you! We''re looking forward to reviewing your additional info.</p>
 <p><br />Sincerely,<br /><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Applicant_FirstName', 'Sender_Email', 'Sender_Signature']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('127', 'Association owner', 'Architectural Request Approved', 'Architectural request approved - "[[Arc_Request_Project_Name]]"', 'Notice sent to an owner when an architectural request at their property has been approved.', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong>
	<br />
	<p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p>
	<p>Your architectural request, "<span class=''token'' contenteditable=''false''>[[Arc_Request_Project_Name]]</span>" was approved.</p>
	<p>All work can now be completed as proposed.</p>
	<p>
		Sincerely,
		<br />
		<span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span>
	</p>', array['Arc_Request_Project_Name', 'Current_Date', 'Homeowner_First_Name', 'Sender_Signature']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('128', 'Association owner', 'Architectural Request Denied', 'Architectural request denied - "[[Arc_Request_Project_Name]]"', 'Notice sent to an owner when an architectural request at their property has been denied.', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong>
	<br />
	<p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p>
	<p>Your architectural request, "<span class=''token'' contenteditable=''false''>[[Arc_Request_Project_Name]]</span>" was denied.</p>
	<p>If you wish to appeal this decision, please follow the appeal guidelines for your community.</p>
	<p>
		Sincerely,
		<br />
		<span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span>
	</p>', array['Arc_Request_Project_Name', 'Current_Date', 'Homeowner_First_Name', 'Sender_Signature']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('123', 'Association owner', 'Association Owner Invoice', 'New invoice for [[Unit_Address_Line_1]]', 'Invoice sent to an owner after charge has been added to their ledger.', '<table style="width:100%;border-spacing:0;border:none;" cellspacing="0" cellpadding="0">
        <tbody>
            <tr>
                <td>
                     <div style="font-size:1.2em"><strong>Unit Address:</strong><br />
                     <span class="token" contenteditable="false">[[Unit_Address]]</span>	
                     </div>
                </td>
                <td>
                    <div style="float:right;"><span style="font-size:28px;"><strong>Invoice</strong></span><br />
                        <span>Invoice number: <span class="token" contenteditable="false">[[Invoice_Number]]</span></span><br />
                        <span>Created: <span class="token" contenteditable="false">[[Invoice_Date]]</span></span><br />
                        <span>Due: <span class="token" contenteditable="false">[[Invoice_Due_Date]]</span></span>
                    </div>
                </td>
            </tr>
        </tbody>
    </table>
    <div>&nbsp;</div>
    <div>&nbsp;</div>
    <table border="1" cellpadding="10" cellspacing="0" style="width:100%">
        <tbody>
            <tr>
                <td style="width:80%;">CHARGE DESCRIPTION</td>
				<td style="text-align:right;width:20%;">TOTAL AMOUNT</td>
            </tr>
            <tr>
                <td class="token" contenteditable="false">[[Invoice_Charge_Name]]</td>
                <td class="token" contenteditable="false">[[Invoice_Charge_Amount]]</td>
            </tr>
        </tbody>
    </table>
    <div>&nbsp;</div>
    <p style="margin-top:5px;margin-bottom:5px;">For your convenience, you can pay this invoice online at <span class="token" contenteditable="false">[[Sender_URL]]</span></p>
    <div>&nbsp;</div>    
    <p>Sincerely,</p>
    <p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Invoice_Charge_Amount', 'Invoice_Charge_Name', 'Invoice_Date', 'Invoice_Due_Date', 'Invoice_Number', 'Sender_Signature', 'Sender_URL', 'Unit_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('120', 'Association owner', 'New violation notice', 'A new violation has been logged at [[Property_Address_Line_1]]', 'Notice sent to an owner when a new violation is logged at their property', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong><br /><p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p><p>A violation has been logged at <span class=''token'' contenteditable=''false''>[[Property_Address_Line_1]]</span>. Please see below for details, and take the necessary steps to resolve this issue.</p><p><br /> <b>Violation: </b><span class=''token'' contenteditable=''false''>[[Violation_Type]]</span></p><p><br /><b>Description: </b><span class=''token'' contenteditable=''false''>[[Violation_Description]]</span><p><br /><b>Required action: </b><span class=''token'' contenteditable=''false''>[[Violation_Action]]</span></p><p><br /><b>Deadline: </b><span class=''token'' contenteditable=''false''>[[Violation_Due_Date]]</span></p><p>Thank you for your cooperation</p><p><br />Sincerely,<br /><span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span></p>', array['Current_Date', 'Homeowner_First_Name', 'Property_Address_Line_1', 'Sender_Signature', 'Violation_Action', 'Violation_Description', 'Violation_Due_Date', 'Violation_Type']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('115', 'Association owner', 'Online Payments Letter', null, 'Encourage association owners to pay association dues online.', '<p>Dear <span class="token" contenteditable="false">[[Homeowner_First_Name]]</span>,</p>
 
 <p>&nbsp;</p>
 
 <p>Did you know you can pay all your <span class="token" contenteditable="false">[[Sender_Name]]</span> bills online? Here are a few reasons we recommend you pay online:</p>
 
 <p>&nbsp;</p>
 
  <ul>
 	<li>It&rsquo;s easy and saves you time. You can literally make payments in seconds.</li>
 	<li>It helps you pay your association dues on time so you avoid late fees.</li>
 	<li>It allows you to set up recurring payments. Never forget to pay your association dues again.</li>
 	<li>It gives you options. Pay via eCheck, debit card, or credit card. &nbsp;</li>
 </ul>
 
 <p>&nbsp;</p>
 
 <p>You can pay your bills online or set up a recurring payment by simply logging into the resident portal at http://<span class="token" contenteditable="false">[[Sender_URL]]</span>.</p>
 
 <p>&nbsp;</p>
 
 <p>If you have any questions, or would like assistance, please let us know by calling <span class="token" contenteditable="false">[[Sender_Phone]]</span>.</p>
 
 <p>&nbsp;</p>
 
 <p>Sincerely,</p>
 
 <p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>
 
 <p>&nbsp;</p>
 
 <div>&nbsp;</div>', array['Homeowner_First_Name', 'Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Sender_URL']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
