<p>&nbsp;</p>', array[]::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('121', 'Association owner', 'Updated violation notice', 'A violation at [[Property_Address_Line_1]] has been updated', 'Notice sent to an owner when a violation at their property has been updated', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong><br /><p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p><p>A violation at <span class=''token'' contenteditable=''false''>[[Property_Address_Line_1]]</span> has been updated. Please see below for details, and take the necessary steps to resolve this issue.</p><p><br /> <b>Violation: </b><span class=''token'' contenteditable=''false''>[[Violation_Type]]</span></p><p><br /><b>Description: </b><span class=''token'' contenteditable=''false''>[[Violation_Description]]</span><p><br /><b>Stage: </b><span class=''token'' contenteditable=''false''>[[Violation_Stage]]</span></p><p><br /><b>Required action: </b><span class=''token'' contenteditable=''false''>[[Violation_Action]]</span></p><p><br /><b>Deadline: </b><span class=''token'' contenteditable=''false''>[[Violation_Due_Date]]</span></p><p>Thank you for your cooperation</p><p><br />Sincerely,<br /><span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span></p>', array['Current_Date', 'Homeowner_First_Name', 'Property_Address_Line_1', 'Sender_Signature', 'Violation_Action', 'Violation_Description', 'Violation_Due_Date', 'Violation_Stage', 'Violation_Type']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('122', 'Association owner', 'Violation resolved notice', 'A violation at [[Property_Address_Line_1]] has been resolved', 'Notice sent to an owner when a violation at their property has been resolved', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong><br /><p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p><p>A violation at <span class=''token'' contenteditable=''false''>[[Property_Address_Line_1]]</span> has been resolved. Thank you for your attention to this matter.</p><p><br /> <b>Violation: </b><span class=''token'' contenteditable=''false''>[[Violation_Type]]</span></p><p><br />Sincerely,<br /><span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span></p>', array['Current_Date', 'Homeowner_First_Name', 'Property_Address_Line_1', 'Sender_Signature', 'Violation_Type']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('110', 'Association owner', 'Welcome Letter', null, 'Welcome letter telling association owners how to access their account information online.', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong><br /><strong>Re: Welcome Letter</strong></p><p>Dear &nbsp;&nbsp;<span class=''token'' contenteditable=''false''>[[Homeowner_First_Name]]</span>,</p><p>We are proud to announce your new owner account for <span class=''token'' contenteditable=''false''>[[Property_Name]]</span>. For your convenience, and to better serve all of our association owners, we offer access to your account information 24 hours a day, from any desktop or mobile device.</p><p>With our online Owner Portal, you can:</p><ul>	<li>Make online payments and view your payment history</li>	<li>Submit service requests directly from your mobile device or computer</li> <li>Access important association documents</li> <li>And much more</li></ul><p>If you have not already received a password and instructions, please point your web browser to our home page at http://<span class=''token'' contenteditable=''false''>[[Sender_URL]]</span></p><p>Once there:</p><ol>	<li>Enter the email address you have on file with us into the Resident Sign In box</li>	<li>Click on &ldquo;Forgot your password? Request a new one&rdquo;</li>	<li>Enter your email address and then wait for a welcome email containing your temporary password</li></ol><p>We hope this service will enhance your experience with us at <span class=''token'' contenteditable=''false''>[[Sender_Name]]</span>. As always, we welcome your feedback and suggestions.</p><p>If you have any questions, or would like assistance registering online, please let us know by calling <span class=''token'' contenteditable=''false''>[[Sender_Phone]]</span>.</p><p><br />Sincerely,<br /><span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span></p>', array['Current_Date', 'Homeowner_First_Name', 'Property_Name', 'Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Sender_URL']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('21519', 'Rental owner', '28 Day Notice Filled', null, '28 days to vacate', '<p><span style="font-size:1.5em">Ghara LLC</span></p>

<p><span style="font-size:1.5em">10115 S HAMPTON DR</span></p>

<p><span style="font-size:1.5em">MILWAUKEE WI 53154</span></p>

<p>&nbsp;</p>

<p style="text-align:center"><span style="font-size:1.5em"><strong>NOTICE TERMINATING TENANCY -TWENTY EIGHT DAY</strong></span></p>

<p style="text-align:center"><span style="font-size:1.5em">28 Day Notice Wis Statues &sect;704.19</span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">State of Wisconsin&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; To:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; RAMON ECHEVARRIA</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Milwaukee County&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2202 S 26th ST Garage</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; MILWAUKEE WI 53215</span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">This notice terminates your tenancy and requires you to remove from the premises described in this notice on or before the&nbsp;<strong><u> 30th&nbsp;&nbsp;</u></strong>&nbsp;day of June 2018</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Description of premises: 2202 S 26th ST Garage, Milwaukee WI 53215.</span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Dated at Milwaukee, WI 53154, this<strong><u>&nbsp; 11th&nbsp;&nbsp;</u></strong>&nbsp; day of May 2018</span></span></p>

<p>&nbsp;</p>

<p>&nbsp;</p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">____________________________&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Albert Harris</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Agent for owner</span></span></p>

<p>&nbsp;</p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Double Rent</strong>. Wisconsin law &sect;704.27 provides that an owner can recover a minimum of twice the daily rent amount for the time the tenant remains in possession&nbsp;</span></span><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">of the unit after expiration of this notice.</span></span></p>

