insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('109', 'Rental owner', 'Property Management Agreement', null, 'Property Management Agreement', '<p><strong>Property Management Agreement</strong></p>
<p><strong>I. Parties</strong><br />
This agreement is between&nbsp;<span>&nbsp;[[Rental_Owner_Full_Name]]</span>&nbsp;(&quot;Owner&quot;), and&nbsp;[[Sender_Name]]&nbsp;(&quot;Manager&quot;). Both parties enter into this agreement for property management services provided by Manager for the properties owned by Owner listed below.&nbsp;</p>
<p>
<p><strong>II. Properties to Be Managed<br />
</strong>Names and addresses of properties to managed under this agreement:</p>
<p>[[Rental_Owner_Properties]]</p>
</p>
<div>
<p>Manager will <strong>OR</strong> will not&nbsp;(choose one) be renting units&nbsp;of the property under a separate written agreement that is not contingent upon or related to this agreement.</p>
</div>
<div><strong>III. Dates/Term<br />
</strong>Manager will begin work on <span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>, 20<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>. This agreement is for a term of month to month. Owner or Manager may cancel this agreement at anytime. Both parties agree, however, to give the other a minimum of 30 days advance notice if possible.</div>
<div>
<p>This agreement may be terminated immediately&nbsp;for any one of the following reasons: <span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>.</p>
</div>
<div>&nbsp;</div>
