insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('112', 'Rental owner', 'Welcome Letter', null, 'Welcome letter telling rental owners how to access their property information online.', '<p><strong>[[Current_Date]]<br />
Re: Welcome Letter<br />
</strong></p>
<p>Dear&nbsp;<span><span>[[Rental_Owner_Full_Name]],</span></span></p>
<p>We are proud to announce our new online Owner Portal.&nbsp;For your convenience, and to better serve your needs, we now offer access to your&nbsp;property&nbsp;information 24 hours a day, from any computer connected online.</p>
<p>With our online Owner Portal,&nbsp;you can:</p>
<ul>
    <li>View your history of owner draws and contributions</li>
   <li>Download&nbsp;your management agreement and other important documents</li>
    <li>View income and expenses for each of your properties</li>
    <li>Run key financial reports on demand</li>
    <li>And much more</li>
</ul>
<p>&nbsp;To get started, following these simple steps:</p>
<ol>
    <li>Point&nbsp;your&nbsp;web browser to our home page at http://[[Sender_URL]]/manager</li>
    <li>Enter your email address and the temporary password you received by email</li>
    <li>Follow the on-screen instructions to change your temporary password</li>
</ol>
<p>We hope this service will enhance your experience&nbsp;with us&nbsp;at&nbsp;[[Sender_Name]].&nbsp;As always, we welcome your feedback and suggestions.</p>
<p>If you have any questions, or would like assistance registering online, please let us know by calling&nbsp;[[Sender_Phone]].</p>
<p>Sincerely,</p>
