insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('50302', 'Tenant', '01_ROCA1_5day_balance', 'Pay Rent OR Vacate', 'Deliver a written notice to tenants to inform them that their monthly rental agreement will be terminated unless they pay their past due rent within a stipulated time frame.', '<p style="text-align: center"><span style="font-size: 1.5em"><span style="font-family: arial, helvetica, sans-serif"><strong>FIVE DAY NOTICE TO PAY RENT OR VACATE PREMISES</strong></span></span></p>

