insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('66741', 'Tenant', '12 Hour  Repairs', 'Notice To Enter', 'Notice for entry', '<table align="center" border="1" cellpadding="1" cellspacing="1" style="height: 50px; width: 500px">
	<tbody>
		<tr>
			<td style="text-align: center">
			<p><strong><span style="font-size: 2em"><span style="font-family: arial, helvetica, sans-serif">12 HOUR NOTICE</span></span></strong></p>

			<p><strong><span style="font-size: 2em"><span style="font-family: arial, helvetica, sans-serif">Wisconsin Statute&nbsp;704.05(2)<br>
			ATCP 134.09(2)(a)1.</span></span></strong></p>
			</td>
		</tr>
	</tbody>
</table>

<p style="text-align: center"><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em"><span contenteditable="false">[[Unit_Address_Line_1]]</span> | <span contenteditable="false">[[Unit_City_Address]]</span>&nbsp;<span contenteditable="false">[[Unit_State_Address]]</span>&nbsp;<span contenteditable="false">[[Unit_PostalCode_Address]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">To:&nbsp;&nbsp;<span contenteditable="false">[[Lease_All_Tenants]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Date:&nbsp;</span></span><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em"><span contenteditable="false">[[Current_Date]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Time:&nbsp;<u>&nbsp; &nbsp; &nbsp; 5:20 pm&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</u></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">This is a 12-hour notice as required by law</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">We will be entering your rental unit 12 hours after the above date and time. Our entry will be at any time between the hours of <u><strong>10:00 a.m. and 1:00 p.m. on&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong></u>. The purpose of our entry is to perform:</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></span></p>

<p><span style="font-size: 2em"><span style="font-family: arial, helvetica, sans-serif">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span><span style="font-family: arial, helvetica, sans-serif"><strong><span style="color: rgba(0, 0, 255, 1)">?***&nbsp;&nbsp;Bathroom water supply &amp; drain lines inspection &amp; possible repairs on an emergency basis.</span></strong></span></span></p>

<p><span style="font-size: 2em"><span style="font-family: arial, helvetica, sans-serif"><strong><span style="color: rgba(0, 0, 255, 1)">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;?***&nbsp;&nbsp;Please answer this QUESTION: Are you taking bath only? Shower only? OR both?</span></strong></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">NOTE:</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em"><strong>Tenants don''t have any rights to deny the landlord entry</strong>, if the landlord has given proper notice.<br>
<strong>Tenants cannot require that the tenant be there during the time that the landlord has chosen to enter</strong>.&nbsp;A tenant isn''t allowed to say, "I have to be here in order for you to come in." If the tenant happens to be there during the time that the landlord has chosen to enter, it''s perfectly allowable under these laws for the tenant to stay.<br>
<strong>A landlord cannot require that a tenant NOT be there during the time that the landlord has chosen to enter</strong>.&nbsp;Similar to the above point, a landlord doesn''t have the right to tell the tenant that they may not be in their home during the landlord''s entry.</span></span></p>

<p>&nbsp;</p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">If you should have any questions or concerns or agrees to the landlord entering the unit at an earlier time please contact us at:</span></span></p>', array['Current_Date', 'Lease_All_Tenants', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
