insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('20732', 'Tenant', 'Breach', null, 'Breach of rental agreement', '<p style="text-align:center"><span style="font-size:1.5em"><strong>FIVE DAY NOTICE TO CORRECT BREACH OR VACATE PREMISES</strong></span></p>

<p style="text-align:center"><span style="font-size:1.5em">5 Day Notice Wis Statues &sect;704.17</span></p>

<p><br />
<span style="font-size:1.5em"><span class="token" contenteditable="false">[[Rental_Owner_Full_Name]]</span></span></p>

<p><span style="font-size:1.5em">414 S 2nd St., Milwaukee WI 53204</span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em">State of Wisconsin&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;To:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="token" contenteditable="false">[[Lease_All_Tenants]]</span></span></p>

<p><span style="font-size:1.5em">Milwaukee County&nbsp;&nbsp;}&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<span class="token" contenteditable="false">[[Unit_Address_Line_1]]</span>,&nbsp;<span class="token" contenteditable="false">[[Unit_Number]]</span></span></p>

<p><span style="font-size:1.5em">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span class="token" contenteditable="false">[[Unit_City_Address]]</span>,&nbsp;<span class="token" contenteditable="false">[[Unit_State_Address]]</span>&nbsp;<span class="token" contenteditable="false">[[Unit_PostalCode_Address]]</span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em">This notice terminates your tenancy pursuant to &sect;704.17, Wisconsin Statutes and requires you, and anyone living with you to vacate the premises described in this notice within <strong>5 days</strong> from service hereof unless you correct the breach listed below within the 5 day period:</span><br />
&nbsp;</p>

<p><span style="font-size:1.5em">You are in breach of your rental agreement for the following reason(s):</span><br />
&nbsp;</p>

<p><span style="font-size:1.5em"><strong>Use Of Premises And Guests</strong></span></p>

<p><span style="font-size:1.5em">Tenant shall use the Premises for residential purposes only. Operating a business or providing child care for children not listed as occupants in this Agreement is prohibited. Neither party may: (1) make or knowingly permit use of the Premises for any unlawful purpose; (2) engage in activities which unduly disturb neighbors or tenants; and/or (3) do, use, or keep in or about the Premises anything which would adversely affect coverage under a standard fire and extended insurance policy. Tenant may have guests residing temporarily in Premises if their presence does not interfere with the quiet use and enjoyment of other tenants and if the number of guests is not excessive for the size and facilities of the Premises.&nbsp;<strong>No guest may remain for more than two (2) weeks without written consent of Landlord</strong>&nbsp;which will not be unreasonably withheld. Tenant shall be liable for any property damage, waste, or neglect of the Premises, building, or development in which it is located, that is caused by the negligence or improper use by Tenant or Tenant&#39;s guests and invitees.<br />
<br />
To cure this breach Tenant MUST either:</span></p>

<p><span style="font-size:1.5em">A)&nbsp; &nbsp; &nbsp;submit an online application for each occupant over 18 years old. Applications are found here:&nbsp;https://yawdcour.managebuilding.com/Resident/public/home</span></p>

<p><br />
<span style="font-size:1.5em">OR&nbsp;</span></p>

<p><br />
<span style="font-size:1.5em">B) Provide proof or residency:</span></p>

<p><span style="font-size:1.5em">You MUST&nbsp;supply &quot;proof or residence&quot; for the other adult(s). We will review any 4 of the following documents with name and current address as proof:<br />
1) Paycheck, stub or earning statement with your employer&#39;s name and address issued within the last 45 days.<br />
2) A utility bill for water, gas, electricity or land-line telephone service issued within the last 45 days. Includes cable and internet services.<br />
3) Mobile phone bills issued in the last 45 days.<br />
4) Deed/title, mortgage, rental/lease agreement for Wisconsin property (lease must include landlord&#39;s name and phone number).<br />
5) Current valid homeowner&#39;s, renter&#39;s or motor vehicle insurance policy dated within the last 12 months.<br />
6) Government-issued correspondence or product issued from a federal, state, county or city agency (original or certified copy issued within the last year).<br />
7) Department of Corrections documentation: Letters from probation/parole agents on letterhead issued within the last 90 days.<br />
8) Certified school record or transcript identifying the person by name and current address and issued within the last 45 days (and for most recent school period).<br />
9) College enrollment documentation.<br />
10) A photo identification card issued by a Wisconsin accredited university, college or technical college that contains the following:&nbsp;<br />
? Date of issuance<br />
? Photo and address of student<br />
? Expiration date no later than two years after date of issuance<br />
11) Employee photo ID card issued by current employer.</span></p>

<p><span style="font-size:1.5em">&nbsp;</span></p>

<p><span style="font-size:1.5em">Dated at Milwaukee, WI 53154, this&nbsp;<u>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</u>day of <span class="token" contenteditable="false">[[Current_Month]]</span> <span class="token" contenteditable="false">[[Current_Year]]</span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em">Landlord / Landlord&rsquo;s Agent:</span></p>

<p><span style="font-size:1.5em"><span class="token" contenteditable="false">[[Rental_Owner_Full_Name]]</span> / Albert Harris</span></p>

<p>&nbsp;</p>

<p>&nbsp;</p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em">_________________________________</span></p>

<p><span style="font-size:1.5em"><span class="token" contenteditable="false">[[Rental_Owner_Full_Name]]</span> / Albert Harris</span></p>

<p><span style="font-size:1.5em">Owner / Agent</span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><strong>Double Rent</strong>: Wisconsin law &sect;704.27 provides that an owner can recover a minimum of twice the daily rent amount for the time the tenant remains in possession of the unit after expiration of this notice.</span></p>

<p>&nbsp;</p>', array['Current_Month', 'Current_Year', 'Lease_All_Tenants', 'Rental_Owner_Full_Name', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_Number', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('41279', 'Tenant', 'Eviction Policy', 'Upcoming Eviction Notice', 'In case Tenants are unable to pay on the 1st.', '<p>Inability to pay rent policy:</p>

<p>Hello</p>

<p>It is our policy to issue a 5 Day Notice to Quit or Pay Rent as required by Wisconsin Statues &sect;704.17 (1) or (2)(a) and/or (2)(b). Therefore: on June 2nd (tomorrow), we will issue said notice.</p>

<p>On Wednesday, June 10th a case will be filed in Milwaukee County Court; IF, your balance is not zero by that date.</p>

<p>On Thursday, June 11th a $280 legal fee will be added to your account; IF a case is filed.</p>

<p>If your balance is not zero on or before the scheduled court date we seek a writ of restitution from the court.</p>

<p>We do understand that family emergencies occur. We also fully understand that families need a roof over their heads and that such a roof often comes with financial expectations. Please make every effort to address this issue.</p>

<p>Sincerely,</p>', array[]::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('113', 'Tenant', 'Lease Renewal Offer', 'Lease Renewal Offer', 'Provide existing tenants with an offer to renew their current lease.', '<p>Dear&nbsp;<span class="token" contenteditable="false">[[Tenant_First_Name]]</span>&nbsp;<span class="token" contenteditable="false">[[Tenant_Last_Name]]</span>,</p><p>It has been a pleasure having you as a resident at&nbsp;<span class="token" contenteditable="false">[[Property_Name]]</span>. Your current lease is expiring on&nbsp;<span class="token" contenteditable="false">[[Lease_End_Date]]</span>.</p><p>We value you as a customer and want to keep you with us. Therefore, we are offering the following renewal terms:</p><p>[[Renewal_Offer]]</p><p>Please reply to this email telling us which offer number you’d like to accept <strong>as soon as possible.</strong></p>[[Intent_MoveOut_Cta]]<p>Thank you very much! If you have any questions, please do not hesitate to reach out via the portal, email <span class="token" contenteditable="false">[[Sender_Email]]</span>, or call <span class="token" contenteditable="false">[[Sender_Phone]]</span>. We look forward to continuing our relationship.</p><p>Sincerely,</p><p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Intent_MoveOut_Cta', 'Lease_End_Date', 'Property_Name', 'Renewal_Offer', 'Sender_Email', 'Sender_Phone', 'Sender_Signature', 'Tenant_First_Name', 'Tenant_Last_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('28273', 'Tenant', 'Move-In Letter', null, 'Provide new tenants with answers to basic questions they may have regarding their lease.', '<p><strong><span class="token" contenteditable="false">[[Current_Date]]</span><br />
Re: Move-In Letter</strong></p>

<p>Dear&nbsp;&nbsp;<span class="token" contenteditable="false">[[Tenant_First_Name]]</span>:&nbsp;</p>

<div>Welcome to&nbsp;<span class="token" contenteditable="false">[[Property_Name]]</span>. For your convenience, we have prepared a move-in packet, which we would like you to return when you move out. This packet should cover all basic questions you may have. You will find information on trash and recycling programs, utility hookups, phone service and instructions for your appliances. It also contains the telephone numbers for the police, fire department, utility companies and other important local services. Please keep these in a safe place so you can reference them when necessary.</div>

<div>&nbsp;</div>

<div>For routine problems, you can reach us at&nbsp;<span class="token" contenteditable="false">[[Sender_Phone]]</span>. If we are not available, please leave a message. Someone will return your call immediately.</div>

<div>
<p>There is a clause in the lease agreement that gives us the right to inspect the property&nbsp;&nbsp;once&nbsp; a year for routine maintenance and safety issues. We usually plan these visits in advance. When we are ready to conduct the inspections, you will be contacted at least&nbsp;&nbsp;5 days&nbsp; in advance to arrange a time that will work best for you. Also, it is important that we always have a key to your property. If you should change the locks for any reason, please be certain to send us copies for emergency access.</p>

<div>Along with your enclosed copy of the lease, we have prepared information on moving out. The Move-Out Checklist lists what will be reviewed during the move-out inspection.</div>

<div>&nbsp;</div>

<div><em>Remember:</em> You must give us a 28 day notice of your intent to move to be in compliance with your lease agreement.</div>

<div>&nbsp;</div>

<div>Thank you once again for selecting&nbsp;<span class="token" contenteditable="false">[[Sender_Name]]</span>. We look forward to having you as a tenant for many years to come.</div>
</div>

<div>
<p>Sincerely,</p>

<p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>
</div>', array['Current_Date', 'Property_Name', 'Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('73266', 'Tenant', 'Move-Out Information', 'Move-Out Information', 'Moving out of a unit', '<p style="text-align: center"><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">ROCA1</span></span></p>

<p style="text-align: center"><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">6626 N Bourbon St.,</span></span></p>

<p style="text-align: center"><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Milwaukee WI 53224</span></span></p>

<p style="text-align: center"><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Tenant Move-Out Procedure</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em"><span contenteditable="false">[[Unit_Address_Line_1]]</span> | <span contenteditable="false">[[Unit_City_Address]]</span> <span contenteditable="false">[[Unit_State_Address]]</span> <span contenteditable="false">[[Unit_PostalCode_Address]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">To:&nbsp; <span contenteditable="false">[[Lease_All_Tenants]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Date: <span contenteditable="false">[[Current_Date]]</span></span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Thank you for renting with us. As your lease ends, please follow the move-out procedures outlined below to ensure a smooth and efficient process:</span></span></p>

<p><strong><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">1. Move-Out Date</span></span></strong></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">You have scheduled a move-out date and we await an update on the timing of your move-out.</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">All personal belongings must be removed, and the unit must be vacated by 12:00 AM on the date you specified.</span></span></p>

<p><strong><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">2. Key Return</span></span></strong></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">All keys (unit, mailbox, and room keys) must be returned by 12:00 AM the date you specified.</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Where to return keys: In Person ONLY in the unit:</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Contact us at 262 236 5443 (text or phone) no less than 2 hours before you intend to return the keys. Leave a voicemail or text message if no one answers.</span></span></p>

<p><strong><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">3. Cleaning Requirements</span></span></strong></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Please leave the unit in a clean and rentable condition. This includes:</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Removing all personal belongings and trash<br>
Cleaning appliances (stove, fridge, microwave, etc.)<br>
Sweeping/mopping all floors<br>
Wiping down all surfaces<br>
Cleaning bathrooms thoroughly<br>
Any items left behind will be discarded and could result in charges.</span></span></p>

<p><strong><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">4. Forwarding Address</span></span></strong></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Please provide a forwarding address for final correspondence.</span></span></p>

<p><strong><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">5. Final Walk-Through (Optional)</span></span></strong></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">If you''d like to schedule a final walk-through with management, please contact us at least 48 hours prior to your move-out date.</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">If you have any questions, feel free to contact us via the Tenant portal, or 262 236 5443.</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">We wish you the best in your next home!</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Sincerely,</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">ROCA1</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">Albert Harris</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">President</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>

<p><span style="font-family: arial, helvetica, sans-serif"><span style="font-size: 1.5em">&nbsp;</span></span></p>', array['Current_Date', 'Lease_All_Tenants', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('104', 'Tenant', 'Move-Out with Written Notice', null, 'Remind tenants who have given written notice to leave their residence in a clean and undamaged condition.', '<p><strong>[[Current_Date]]<br />
Re: Move-Out Reminder<br />
</strong></p>
<p>Dear&nbsp;<span><span>&nbsp;[[Tenant_First_Name]]</span></span>:&nbsp;</p>
<div>
<p>Thank you for giving us advance notice of your intent to move. Your lease/rental agreement requires that you leave your residence in clean and undamaged condition. We have every intention of returning your entire security deposit as long as you have fulfilled your agreement with us.&nbsp;</p>
<div>Specifically, you should:</div>
<ul type="disc">
    <li>Cooperate with the showing of the residence for sale or rental, keeping it in presentable condition</li>
    <li>Begin to discard all unwanted items for trash or special pick-up&mdash;avoid piles of debris in front of your residence on moving day</li>
    <li>Remove all food, debris and other personal belongings</li>
    <li>Clean (and defrost if necessary) refrigerator</li>
    <li>Clean stove, oven and any other appliances</li>
    <li>Replace any burned out light bulbs</li>
    <li>Clean all floors and/or carpeting</li>
    <li>Be sure grounds and lawn are trim, clean and free of weeds and leaves</li>
    <li>Report any and all damage in writing</li>
    <li>Upon leaving, please be sure to fully secure the rental by locking all windows and doors&nbsp;</li>
</ul>
<div>After you have vacated the residence, it will be inspected for compliance with your</div>
<div>lease/rental agreement. Costs for cleaning or repairing damage beyond normal wear and tear, if any, will be charged against your security deposit. You will be provided with an itemized list of any charges incurred.</div>
<p>Sincerely,</p>
<p>[[Sender_Signature]]</p>
</div>', array['Current_Date', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('105', 'Tenant', 'Move-Out without Written Notice', null, 'Remind tenants who have not given written notice that one is required prior to vacating their residence.', '<p><strong>[[Current_Date]]<br />
Re: Move-Out Letter<br />
</strong></p>
<p>Dear&nbsp;<span><span>&nbsp;[[Tenant_First_Name]]</span></span>:&nbsp;</p>
<div>
<p>Per our lease agreement, your move-out notice must be received 30 days prior to vacating.&nbsp;</p>
<div>The general rule&mdash;per our contract&mdash;is that if we are unable to lease the residence in the period that you are still under contract, you are obligated to pay that rent. Also, once you have moved out from the residence, it will be inspected for cleanliness and damage. If the residence is left in good condition, your security deposit will be returned to you in full&mdash;provided you do not owe back rent or miscellaneous expenses. In such cases, the monies will go toward these expenses, and the difference will be released to you.</div>
<div>&nbsp;</div>
<div>Please review the Move-Out Checklist, which you received when you moved in&mdash;give each item your personal attention before departing.</div>
<div><br />
Please contact the utility services, and phone and cable companies to disconnect all services in your name to avoid being billed for unneeded services.</div>
<div>&nbsp;</div>
<div>It has been wonderful having you as a tenant and we wish you many years of happiness in your new residence.</div>
<p>Sincerely,</p>
<p>[[Sender_Signature]]</p>
</div>', array['Current_Date', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('20259', 'Tenant', 'Notice of Change of Rent', 'Notice of Change of Rent', 'Notify tenants of an increase in rent.', '<p><strong><span style="font-size:1.5em"><span class="token" contenteditable="false">[[Current_Date]]</span></span><br />
<span style="font-size:1.5em">Re: Notice of Change of Rent</span></strong></p>

<p><span style="font-size:1.5em">Dear&nbsp;&nbsp;<span class="token" contenteditable="false">[[Tenant_First_Name]]</span>:&nbsp;</span></p>

<div>
<p><span style="font-size:1.5em">This is to give you notice that, effective&nbsp;January 1st, 2021, the rent for the unit you now occupy at&nbsp; <span class="token" contenteditable="false">[[Property_Address_Line_1]]</span>&nbsp;will be increased from&nbsp;<span class="token" contenteditable="false">[[Lease_Rent]]</span> per month to Six Hundred and Twenty-Five Dollars<strong> ($625.00)</strong>, payable on or before the first&nbsp;day of the month.</span></p>

<div>
<p><span style="font-size:1.5em">Our buildings are deficient in key areas and we must actively begin repairs and maintenance. All other terms of the rental agreement will remain in effect.</span></p>
</div>

<p><span style="font-size:1.5em">Sincerely,</span></p>

<p><span style="font-size:1.5em"><span class="token" contenteditable="false">[[Sender_Signature]]</span></span></p>
</div>', array['Current_Date', 'Lease_Rent', 'Property_Address_Line_1', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('100', 'Tenant', 'Notice that Eviction will be Filed in Court', null, 'Notify tenants who are delinquent on rental payments that they will be evicted. This form allows you to legally retain a security deposit and require that the tenants vacate the premises.', '<p><strong>[[Current_Date]]<br />
Re: <strong>Notice that Eviction will be Filed in Court</strong></strong></p>
<p>Dear&nbsp;<span><span>&nbsp;[[Tenant_First_Name]]</span></span>:&nbsp;</p>
<div>
<p>A&nbsp;5<span><span>&nbsp;</span></span>-day notice has been given to you in accordance with state and local laws and you have failed to either cure the violation of your Lease Agreement or to vacate the premises.&nbsp;</p>
<p>[[Sender_Name]]&nbsp;will therefore no longer accept any payment of rents due from you. All amounts you still owe will be set off against your security deposit, and the remaining balance will form part of a claim, which&nbsp;[[Sender_Name]]&nbsp;will file against you.</p>
<p>Sincerely,</p>
<p>[[Sender_Signature]]</p>
</div>', array['Current_Date', 'Sender_Name', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('15869', 'Tenant', 'Notice to Pay Rent or Quit - RH', '', 'Deliver a written notice to tenants to inform them that their monthly rental agreement will be terminated unless they pay their past due rent within a stipulated time frame.', '<p style="text-align:center"><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>FIVE DAY NOTICE TO PAY RENT OR VACATE PREMISES</strong></span></span></p>

<p style="text-align:center"><span style="font-size:1em"><span style="font-family:arial,helvetica,sans-serif">5 Day Notice Wis Statues &sect;704.17 (1) or (2)(a) and/or (2)(b)</span></span></p>

<p><span style="font-size:1.5em"><span class="token" contenteditable="false">[[Rental_Owner_Full_Name]]</span></span></p>

<p><span style="font-size:1.5em">735 Burr Oak Place&nbsp; Rice Lake, WI 54868</span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">State of Wisconsin&nbsp;&nbsp; }&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong> To:</strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="token" contenteditable="false">[[Lease_All_Tenants]]</span></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Milwaukee County&nbsp;&nbsp;}&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span class="token" contenteditable="false">[[Unit_Address_Line_1]]</span>,&nbsp;<span class="token" contenteditable="false">[[Unit_Number]]</span></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span class="token" contenteditable="false">[[Unit_City_Address]]</span>,&nbsp;<span class="token" contenteditable="false">[[Unit_State_Address]]</span>&nbsp;<span class="token" contenteditable="false">[[Unit_PostalCode_Address]]</span></span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">This notice terminates your tenancy pursuant to &sect;704.17 (1) or (2)(a) and/or (2)(b), Wisconsin Statutes and requires you to vacate the premises described in this notice within&nbsp;5 days&nbsp;from service hereof&nbsp;unless you pay&nbsp;the total unpaid rent of&nbsp;<span class="token" contenteditable="false">[[Lease_Rent]]</span>&nbsp;which was due on&nbsp;<span class="token" contenteditable="false">[[Lease_Rent_Due_Day]]</span>&nbsp;day of <span class="token" contenteditable="false">[[Current_Month]]</span>&nbsp;<span class="token" contenteditable="false">[[Current_Year]]</span>.</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Description of premises:&nbsp;<span class="token" contenteditable="false">[[Unit_Address_Line_1]]</span>,&nbsp;<span class="token" contenteditable="false">[[Unit_Number]]</span>,&nbsp;Milwaukee WI&nbsp;<span class="token" contenteditable="false">[[Unit_PostalCode_Address]]</span>.</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">The amount was calculated as follows:</span></span></p>

<table border="1" cellpadding="0" cellspacing="0" style="width:700px">
	<tbody>
		<tr>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><span class="token" contenteditable="false">[[Current_Month]]</span>&nbsp;<span class="token" contenteditable="false">[[Current_Year]]</span>&nbsp;unpaid rent</span></span></td>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><span class="token" contenteditable="false">[[Lease_Rent]]</span></span></span></td>
		</tr>
		<tr>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Amount due prior to&nbsp;<span class="token" contenteditable="false">[[Current_Month]]</span>&nbsp;<span class="token" contenteditable="false">[[Current_Year]]</span></span></span></td>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">$0.00</span></span></td>
		</tr>
		<tr>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Total Due</span></span></td>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><span class="token" contenteditable="false">[[Lease_Rent]]</span></span></span></td>
		</tr>
		<tr>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Amount required to avoid eviction (excludes late fees)</span></span></td>
			<td><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><span class="token" contenteditable="false">[[Lease_Rent]]</span></span></span></td>
		</tr>
	</tbody>
</table>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Note</strong>: The above amount required to avoid eviction&nbsp;excludes&nbsp;unpaid late fees,&nbsp;if any. To have a zero balance, you must pay the total amount due.</span></span></p>

<p><br />
<span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Dated at Milwaukee, WI 53206, this&nbsp;<u>&nbsp;2nd&nbsp;&nbsp;</u>&nbsp;day of&nbsp;<span class="token" contenteditable="false">[[Current_Month]]</span>&nbsp;<span class="token" contenteditable="false">[[Current_Year]]</span></span></span></p>

<p><br />
<span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Landlord / Landlord&#39;s Agent:</strong></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><span class="token" contenteditable="false">[[Rental_Owner_Full_Name]]</span>&nbsp;/ Albert Harris</span></span></p>

<p>&nbsp;</p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">__________________________________</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Agent</span></span><br />
&nbsp;</p>

<hr />
<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Non Waiver</strong>:&nbsp;If you make a payment of&nbsp;less than the&nbsp;<span class="token" contenteditable="false">[[Lease_Rent]]</span>&nbsp;required by this notice, you will still be in default and&nbsp;SUBJECT TO EVICTION&nbsp;unless the Owner agrees in writing to cancel this notice.</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Credit reporting</strong>:&nbsp;We may report delinquent accounts to credit bureaus. This may affect your ability to obtain credit and or your ability to rent in the future</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif"><strong>Double Rent</strong>:&nbsp;Wisconsin law &sect;704.27 provides that an owner can recover a&nbsp;minimum of twice the daily rent&nbsp;amount for the time the tenant remains in possession of the unit after expiration of this notice.</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Skipping out&nbsp;is against the law in Wisconsin. Statute 943.215: &quot;Absconding without paying rent. (1) Whoever having obtained the tenancy, as defined in s. 704.01 (4) of residential property he or she is entitled to occupy, intentionally absconds without paying all current and past due rent is guilty of a Class A misdemeanor.&quot;</span></span></p>

<hr />
<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Arrangement for payment can be made through your <a href="https://yawdcour.managebuilding.com/Resident/public/home" target="_blank">Tenant Portal</a></span></span></p>', array['Current_Month', 'Current_Year', 'Lease_All_Tenants', 'Lease_Rent', 'Lease_Rent_Due_Day', 'Rental_Owner_Full_Name', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_Number', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('114', 'Tenant', 'Online Payments Letter', null, 'Encourage tenants to pay rent online.', '<p>Dear <span class="token" contenteditable="false">[[Tenant_First_Name]]</span>,</p>
 
 <p>&nbsp;</p>
 
 <p>Did you know you can pay all your <span class="token" contenteditable="false">[[Sender_Name]]</span> bills online? Here are a few reasons we recommend you pay online:</p>
 
 <p>&nbsp;</p>
 
 <ul>
 	<li>It&rsquo;s easy and saves you time. You can literally make payments in seconds.</li>
 	<li>It helps you pay your rent on time so you avoid late fees.</li>
 	<li>It allows you to set up recurring payments. Never forget to pay your rent again.</li>
 	<li>It gives you options. Pay via eCheck, debit card, or credit card. &nbsp;</li>
 </ul>
 
 <p>&nbsp;</p>
 
 <p>You can pay your bills online or set up a recurring payment by simply logging into the resident portal at http://<span class="token" contenteditable="false">[[Sender_URL]]</span>.</p>
 
 <p>&nbsp;</p>
 
 <p>If you have any questions, or would like assistance, please let us know by calling <span class="token" contenteditable="false">[[Sender_Phone]]</span>.</p>
 
 <p>&nbsp;</p>
 
 <p>Sincerely,</p>
 
 <p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Sender_URL', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('28274', 'Tenant', 'Past Due Rent - Notice', null, 'First notice informing tenant that their rent is past due.', '<p><strong><span class="token" contenteditable="false">[[Current_Date]]</span></strong></p>

<p><strong>Dear&nbsp;&nbsp;<span class="token" contenteditable="false">[[Tenant_First_Name]]</span>:&nbsp;</strong></p>

<p><span style="font-size:1.5em">Per our lease agreement, your rent is due on the first day of each month. Your rent is late on the 2nd day of the month and a late fee will be posted to your account. Furthermore, a 5-day notice is mailed via certified mailing on the 2nd day of the month. This gives you 5 days from the date on the mailing&nbsp;to meet your monthly obligation without eviction procedures.&nbsp;&nbsp;</span></p>

<p><span style="font-size:1.5em">Please&nbsp;<u>disregard</u>&nbsp;the 5-Day Notice -&nbsp;<strong><u>IF</u></strong>&nbsp;- you have made payments in full to bring your balance to zero. If <strong><u>NOT</u></strong> -&nbsp; an escalation of penalties and eviction filing in court will ensue.</span></p>

<p><span style="font-size:1.5em">Sincerely,</span></p>

<div>
<p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>
</div>', array['Current_Date', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('101', 'Tenant', 'Past Due Rent - Second Notice', null, 'Second notice informing tenant that his or her rent is past due, so any further action you may need to take will have the proper legal basis.', '<p><strong>[[Current_Date]]<br />
Re: Past Due Rent - Second Notice<br />
</strong></p>
<p>Dear&nbsp;<span><span>&nbsp;[[Tenant_First_Name]]</span></span>:&nbsp;</p>
<div>
<p>This notice is to advise you that as of [[Current_Date]]&nbsp;your balance of&nbsp;[[Statement_Balance]] has not been received in accordance with the terms of your lease agreement.</p>
<p>In accordance with the terms of the lease, if we have not received your payment within <span>5 </span>days, we will be forced to take any and all legal action in accordance with your lease agreement and state law. These actions may include, but are not necessarily limited to, termination of the lease, eviction, and any resultant damages thereto including costs, disbursements, and attorney&rsquo;s fees associated with any related action in this regard.&nbsp;</p>
<div>Please contact&nbsp;[[Sender_Name]] at&nbsp;[[Sender_Phone]]&nbsp;if you have any questions.</div>
<p>Sincerely,</p>
<p>[[Sender_Signature]]</p>
</div>', array['Current_Date', 'Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Statement_Balance', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
