			<td style="vertical-align: top; width: 297pt">
			<p><span style="font-family: times new roman, serif; font-size: 16px"><span contenteditable="false">[[Unit_City_Address]]</span> <span contenteditable="false">[[Unit_State_Address]]</span>&nbsp;<span contenteditable="false">[[Unit_PostalCode_Address]]</span></span></p>
			</td>
		</tr>
	</tbody>
</table>

<p><span style="font-family: arial, sans-serif; font-size: 13px">&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">We appreciate your tenancy with us and would like you to remain as a tenant. Due to general cost increases, it has become necessary to raise your rent. You are a <strong>month-to-month</strong> tenant and your current rent is $<span contenteditable="false">[[Lease_Rent]]</span> per month.&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">Effective </span> ______________________<span style="font-family: arial, sans-serif; font-size: 13px"> (date the amount of the rent increase goes into effect) your rent will be increased to $___________ per month.&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">&nbsp;</span></p>

<p><strong><span style="font-family: arial, sans-serif; font-size: 13px">Address of the property</span></strong><span style="font-family: arial, sans-serif; font-size: 13px">:</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px"><span contenteditable="false">[[Unit_Address_Line_1]]</span></span><span style="font-family: arial, sans-serif; font-size: 13px">&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px"><span contenteditable="false">[[Unit_City_Address]]</span>&nbsp;<span contenteditable="false">[[Unit_State_Address]]</span>&nbsp;<span contenteditable="false">[[Unit_PostalCode_Address]]</span></span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">All other terms of your rental agreement will remain the same.&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">&nbsp;</span><strong><span style="font-family: arial, sans-serif; font-size: 13px">Abandoned property</span></strong><span style="font-family: arial, sans-serif; font-size: 13px">: Landlord will not store any items of personal property that Tenant leaves behind when Tenant vacates or is evicted from the premises, except for prescription medicine or prescription medical equipment which will be held for seven (7) days from the date of discovery. If Tenant abandons a manufactured or mobile home or a titled vehicle, Landlord will give Tenant and any other secure party that Landlord is aware of, written notice of intent to dispose of property by personal service, regular Mail, or certified Mail to tenants last known address, prior to disposal.</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">Thank you for understanding.</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">Date</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">Dated at Milwaukee, WI 53206, this _____ day of ______ ________.</span></p>

<p><strong><span style="font-family: arial, sans-serif; font-size: 13px">Landlord / Landlord''s Agent:</span></strong></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">&nbsp;</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">__________________________________</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px"><span contenteditable="false">[[Rental_Owner_Full_Name]]</span> / Manjit</span></p>

<p><span style="font-family: arial, sans-serif; font-size: 13px">Owner / Agent</span></p>', array['Lease_Rent', 'Property_Address_Line_1', 'Rental_Owner_Full_Name', 'Tenant_First_Name', 'Tenant_Last_Name', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('124', 'Tenant', 'Tenant Invoice', 'New invoice for [[Unit_Address_Line_1]]', 'Invoice sent to a tenant after charge has been added to their ledger.', '<table style="width:100%;border-spacing:0;border:none;" cellspacing="0" cellpadding="0">
	<tbody>
		<tr>
			<td>
				 <div style="font-size:1.2em"><strong>Unit Address:</strong><br />
					<span class="token" contenteditable="false">[[Unit_Address]]</span>	
				</div>
			</td>
			<td>
				<div style="float:right;"><span style="font-size:28px;"><strong>Invoice</strong></span><br />
					<span>Invoice number: <span class="token" contenteditable="false">[[Invoice_Number]]</span></span><br />
					<span>Created: <span class="token" contenteditable="false">[[Invoice_Date]]</span></span><br />
					<span>Due: <span class="token" contenteditable="false">[[Invoice_Due_Date]]</span></span>
				</div>
			</td>
		</tr>
	</tbody>
    </table>
    <div>&nbsp;</div>
    <div>&nbsp;</div>
    <table border="1" cellpadding="10" cellspacing="0" style="width:100%">
        <tbody>
			<tr>
				<td style="width:80%;">CHARGE DESCRIPTION</td>
				<td style="text-align:right;width:20%;">TOTAL AMOUNT</td>
			</tr>
			<tr>
				<td class="token" contenteditable="false">[[Invoice_Charge_Name]]</td>
				<td class="token" contenteditable="false">[[Invoice_Charge_Amount]]</td>
			</tr>
		</tbody>
    </table>
    <div>&nbsp;</div>
    <p>For your convenience, you can pay this invoice online at <span class="token" contenteditable="false">[[Sender_URL]]</span></p>
    <div>&nbsp;</div>
    <p>Sincerely,</p>
    <p><span class="token" contenteditable="false">[[Sender_Signature]]</span></p>', array['Invoice_Charge_Amount', 'Invoice_Charge_Name', 'Invoice_Date', 'Invoice_Due_Date', 'Invoice_Number', 'Sender_Signature', 'Sender_URL', 'Unit_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('102', 'Tenant', 'Violation of Pet Policy', null, 'Notify tenants when they violate the pet policy of their lease agreement.', '<p><strong>[[Current_Date]]<br />
Re: Violation of Pet Policy<br />
</strong></p>
<p>Dear&nbsp;<span><span>&nbsp;[[Tenant_First_Name]]</span></span>:&nbsp;</p>
<div>
<p>By signing a lease agreement, we have both made a binding commitment. The Management promised a safe and clean residence and you promised to live up to the terms of the agreement.&nbsp;</p>
<div>We recently learned that you have violated the lease agreement. You have a pet&nbsp;in your residence, which your lease strictly prohibits. When you were given the lease, this clause was brought to your attention, and you confirmed your acceptance of it by signing the lease.</div>
<div>&nbsp;</div>
<div>To avoid further discussion on this matter, please confirm in writing&nbsp;that you have permanently removed the pet <span>from your residence.</span></div>
<p>Sincerely,</p>
<p>[[Sender_Signature]]</p>
</div>', array['Current_Date', 'Sender_Signature', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('41903', 'Tenant', 'WRAP', 'Help For Paying Rent', 'Housing', '<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Hello -&nbsp;<span class="token" contenteditable="false">[[Tenant_First_Name]]</span></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Call this number NOW! <u><strong>(414) 326-2888</strong></u> Do Not Wait! You <u><strong>MUST </strong></u>Call!</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Be ready to leave a message, so practice what you will say prior to calling. Say this ONLY, then hang up:</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">My Name is:&nbsp;<strong><span class="token" contenteditable="false">[[Tenant_First_Name]]</span></strong>&nbsp;<strong><span class="token" contenteditable="false">[[Tenant_Last_Name]]</span></strong>&nbsp;:&nbsp; Then spell your name!</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">My Address is:&nbsp;<strong><span class="token" contenteditable="false">[[Unit_Address_Line_1]]</span></strong>,&nbsp;<strong><span class="token" contenteditable="false">[[Unit_City_Address]]</span></strong>,&nbsp;<strong><span class="token" contenteditable="false">[[Unit_State_Address]]</span></strong>,&nbsp;<strong><span class="token" contenteditable="false">[[Unit_PostalCode_Address]]</span></strong></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">My County is: <strong>Milwaukee</strong></span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Then say &quot;I need rent assistance&quot;</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Then hang up</span></span></p>

<p><span style="font-size:1.5em"><span style="font-family:arial,helvetica,sans-serif">Call Or Text me at&nbsp;<span style="color:rgb(32, 33, 36)"><strong>(262) 236-5443</strong>&nbsp;and tell me that you made the call so I can start preparing your paperwork.</span></span></span></p>', array['Tenant_First_Name', 'Tenant_Last_Name', 'Unit_Address_Line_1', 'Unit_City_Address', 'Unit_PostalCode_Address', 'Unit_State_Address']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
insert into letter_templates (buildium_id, recipient, name, subject, description, html, fields) values ('111', 'Tenant', 'Welcome Letter', null, 'Welcome letter telling tenants how to access their account information online.', '<p><strong><span class=''token'' contenteditable=''false''>[[Current_Date]]</span></strong><br /><strong>Re: Welcome Letter</strong></p><p><br />Dear &nbsp;<span class=''token'' contenteditable=''false''>[[Tenant_First_Name]]</span>,</p><p>We are proud to announce our new and improved online resident site for <span class=''token'' contenteditable=''false''>[[Property_Name]]</span>. For your convenience, and to better serve all of our tenants, we offer access to your account information 24 hours a day, from your desktop or mobile device.</p><p>With our online resident site, you can:</p><ul>	<li>Pay rent online and view your payment history</li>	<li>Set up automatic monthly payments</li>	<li>Submit maintenance requests directly from your mobile device or computer</li>	<li>View and download important documents like your lease agreement</li> <li>And much more</li></ul><p>If you have not already received a password and instructions, please go to our home page at http://<span class=''token'' contenteditable=''false''>[[Sender_URL]]</span></p><p>Once there:</p><ol>	<li>Enter the email address you have on file with us into the Resident Sign In box</li>	<li>Click on &ldquo;Forgot your password? Request a new one&rdquo;</li>	<li>Enter your email address and then wait for a welcome email containing your temporary password</li></ol><p>We hope this service will enhance your experience with us at <span class=''token'' contenteditable=''false''>[[Sender_Name]]</span>. As always, we welcome your feedback and suggestions.</p><p>If you have any questions, or would like assistance registering online, please let us know by calling <span class=''token'' contenteditable=''false''>[[Sender_Phone]]</span>.</p><p><br />Sincerely,<br /><span class=''token'' contenteditable=''false''>[[Sender_Signature]]</span></p>', array['Current_Date', 'Property_Name', 'Sender_Name', 'Sender_Phone', 'Sender_Signature', 'Sender_URL', 'Tenant_First_Name']::text[]) on conflict (buildium_id) do update set html = excluded.html, fields = excluded.fields, subject = excluded.subject, description = excluded.description;
commit;
